1	// Fault-injection shims for the regression-test build of envelopefile.
2	//
3	// This file is linked together with src/main.cpp into the separate
4	// `envelopefile_testable` binary using the linker's --wrap option, so every
5	// open/write/fsync/close call made by the product code is routed through the
6	// __wrap_* functions below. The production binary is completely unaffected.
7	//
8	// Injection is controlled entirely through environment variables so the test
9	// driver can select a scenario per process run:
10	//
11	//   EF_TEST_TARGET          Only inject faults for this exact path. When
12	//                           unset, any file created with O_CREAT|O_EXCL is
13	//                           considered the key file under test.
14	//   EF_TEST_FAIL_WRITE=1    write() on the key file fails with EIO.
15	//   EF_TEST_PARTIAL_WRITE=N write() on the key file returns at most N bytes
16	//                           per call (the caller must loop to complete).
17	//   EF_TEST_FAIL_FSYNC=1    fsync() on the key file fails with EIO.
18	//   EF_TEST_FAIL_CLOSE=1    close() on the key file reports EIO (the
19	//                           descriptor is still really closed, matching the
20	//                           POSIX guarantee that close() releases the fd).
21	//
22	// For deterministic coverage of the write loop itself, a per-call script can
23	// be supplied:
24	//
25	//   EF_TEST_WRITE_SCRIPT=t1,t2,...
26	//                           Each token describes the outcome of one write()
27	//                           call on the key file, consumed in order; once the
28	//                           list is exhausted every further call succeeds
29	//                           normally. Tokens:
30	//                             ok    - write the whole requested buffer
31	//                             N     - short write: at most N (decimal) bytes
32	//                             intr  - fail with EINTR, no bytes written
33	//                             eio   - fail irrecoverably with EIO
34	//                             zero  - return 0 with bytes still pending
35	//
36	//   EF_TEST_WRITE_LOG=path  Record what the write loop actually did, so the
37	//                           test driver can prove byte continuity across
38	//                           retries. On the first key-file write the original
39	//                           32-byte key is snapshotted; every subsequent call
40	//                           is checked to advance from the current offset with
41	//                           a buffer that is a slice of that same snapshot
42	//                           (i.e. the key is neither regenerated, duplicated,
43	//                           nor dropped). Every call is also checked to pass a
44	//                           pointer INTO the exact buffer RAND_bytes filled
45	//                           (at the current offset), so the bytes that reach
46	//                           the file are provably the ones the later
47	//                           OPENSSL_cleanse wipes — not a copy living
48	//                           elsewhere. The file receives one line:
49	//                             VERIFY <64 lowercase hex digits>
50	//                           followed by one line per write() call:
51	//                             CALL <offset> <requested> <returned> [<errno>]
52	//                           (the errno field is only present when returned is
53	//                           -1). A continuity violation is recorded as a
54	//                             VERIFY-FAILED <reason>
55	//                           line and aborts the process, since it means the
56	//                           product code violated its own write contract.
57	//
58	// The secure random source can be made to fail deterministically:
59	//
60	//   EF_TEST_FAIL_RAND=1       RAND_bytes reports failure (returns 0).
61	//   EF_TEST_RAND_PARTIAL=N    before failing, N marker bytes (0xA5) are
62	//                             written into the caller's key buffer,
63	//                             simulating a CSPRNG that dies mid-fill. The
64	//                             marker lets the test driver prove the partial
65	//                             data is neither saved nor leaked.
66	//   EF_TEST_RAND_ERROR_DETAIL=1
67	//                             leave a descriptive OpenSSL error on the
68	//                             thread's error queue so the failure carries
69	//                             detail text; when unset the queue is cleared
70	//                             instead, exercising the no-detail message.
71	//
72	// Key-buffer lifecycle events are recorded when requested:
73	//
74	//   EF_TEST_KEY_LOG=path      one line per event:
75	//                               RAND <requested> partial=<N> result=<ok|fail>
76	//                               CLEANSED-KEY <len>
77	//                               CLEANSE-STATE writes=<N> keyfd=<open|closed>
78	//                             The CLEANSED-KEY line is emitted when the
79	//                             buffer previously handed to RAND_bytes is
80	//                             wiped via OPENSSL_cleanse, proving the key
81	//                             (including any partial bytes) does not survive
82	//                             the operation in memory. It is followed by a
83	//                             CLEANSE-STATE line capturing how many key bytes
84	//                             had been written and whether the key-file
85	//                             descriptor was already closed at that moment,
86	//                             so the test driver can prove the wipe happened
87	//                             only after the save was complete (never before,
88	//                             which would save wiped data).
89	//
90	// Only the file descriptor opened for the key file is instrumented; all
91	// other I/O (stdout, stderr, OpenSSL internals, the log file itself) passes
92	// through untouched.
93	
94	#include <openssl/err.h>
95	#include <openssl/opensslv.h>
96	#include <openssl/rand.h>
97	
98	#include <cerrno>
99	#include <cstdarg>
100	#include <cstdint>
101	#include <cstdio>
102	#include <cstdlib>
103	#include <cstring>
104	#include <fcntl.h>
105	#include <unistd.h>
106	
107	extern "C" {
108	
109	// Real libc/libcrypto entry points provided by the --wrap linker mechanism.
110	int __real_open(const char* path, int flags, ...);
111	ssize_t __real_write(int fd, const void* buffer, size_t count);
112	int __real_fsync(int fd);
113	int __real_close(int fd);
114	int __real_RAND_bytes(unsigned char* buf, int num);
115	void __real_OPENSSL_cleanse(void* ptr, size_t len);
116	
117	namespace {
118	
119	constexpr std::size_t kKeyBytes = 32;
120	
121	// Descriptor currently known to belong to the key file under test, or -1.
122	int g_keyFd = -1;
123	
124	// Key buffer most recently handed to RAND_bytes, so the OPENSSL_cleanse
125	// wrapper can recognise (and log) its wipe.
126	unsigned char* g_randBuf = nullptr;
127	int g_randBufSize = 0;
128	
129	// Continuity bookkeeping for EF_TEST_WRITE_LOG.
130	unsigned char g_keySnapshot[kKeyBytes];
131	bool g_haveSnapshot = false;     // the snapshot below is valid
132	std::size_t g_progress = 0;      // bytes acknowledged so far (pre-call offset)
133	
134	bool envFlagSet(const char* name) {
135	    const char* value = std::getenv(name);
136	    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
137	}
138	
139	bool isKeyPath(const char* path) {
140	    const char* target = std::getenv("EF_TEST_TARGET");
141	    return target == nullptr || std::strcmp(path, target) == 0;
142	}
143	
144	bool isKeyFd(int fd) {
145	    return fd != -1 && fd == g_keyFd;
146	}
147	
148	// Preserve errno across the bookkeeping I/O so the injected failure code is
149	// what the product code actually observes.
150	class ErrnoSaver {
151	public:
152	    ErrnoSaver() : saved_(errno) {}
153	    ~ErrnoSaver() { errno = saved_; }
154	
155	private:
156	    int saved_;
157	};
158	
159	void logLine(const char* pathEnv, const char* mode, const char* text) {
160	    const char* logPath = std::getenv(pathEnv);
161	    if (logPath == nullptr || logPath[0] == '\0') {
162	        return;
163	    }
164	    ErrnoSaver saver;
165	    std::FILE* file = std::fopen(logPath, mode);
166	    if (file == nullptr) {
167	        return;
168	    }
169	    std::fputs(text, file);
170	    std::fputc('\n', file);
171	    std::fclose(file);
172	}
173	
174	void logKeyLine(const char* text) {
175	    logLine("EF_TEST_KEY_LOG", "a", text);
176	}
177	
178	void logVerifyHeader(const unsigned char* buffer) {
179	    constexpr std::size_t kPrefix = 7;  // strlen("VERIFY ")
180	    char line[kPrefix + 2 * kKeyBytes + 1];
181	    char* out = line;
182	    std::strcpy(out, "VERIFY ");
183	    out += 7;
184	    static const char hex[] = "0123456789abcdef";
185	    for (std::size_t i = 0; i < kKeyBytes; ++i) {
186	        *out++ = hex[buffer[i] >> 4];
187	        *out++ = hex[buffer[i] & 0x0f];
188	    }
189	    *out = '\0';
190	    logLine("EF_TEST_WRITE_LOG", "w", line);
191	}
192	
193	void logCall(std::size_t offset, std::size_t requested,
194	             ssize_t returned, int reportedErrno) {
195	    char line[128];
196	    if (returned < 0) {
197	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd %d",
198	                      offset, requested, returned, reportedErrno);
199	    } else {
200	        std::snprintf(line, sizeof(line), "CALL %zu %zu %zd",
201	                      offset, requested, returned);
202	    }
203	    logLine("EF_TEST_WRITE_LOG", "a", line);
204	}
205	
206	void logVerifyFailed(const char* reason) {
207	    char line[160];
208	    std::snprintf(line, sizeof(line), "VERIFY-FAILED %s", reason);
209	    logLine("EF_TEST_WRITE_LOG", "a", line);
210	}
211	
212	// On the first key-file write, snapshot the key; afterwards confirm that the
213	// caller resumes exactly at the acknowledged offset and presents the matching
214	// slice of the same key. Every call must also pass a pointer into the very
215	// buffer RAND_bytes filled (at the current offset): the bytes reaching the
216	// file are then provably the ones OPENSSL_cleanse later wipes, not an
217	// unwiped copy. Any mismatch is a product-code defect: abort so the
218	// regression run can never pass on a silently regenerated/garbled key.
219	void verifyIncomingBuffer(const void* buffer, std::size_t count) {
220	    if (std::getenv("EF_TEST_WRITE_LOG") == nullptr) {
221	        return;
222	    }
223	    const auto* bytes = static_cast<const unsigned char*>(buffer);
224	    if (g_randBuf != nullptr && bytes != g_randBuf + g_progress) {
225	        logVerifyFailed("write buffer is not the buffer filled by RAND_bytes");
226	        std::abort();
227	    }
228	    if (!g_haveSnapshot) {
229	        if (count != kKeyBytes) {
230	            logVerifyFailed("first write did not carry the whole 32-byte key");
231	            std::abort();
232	        }
233	        std::memcpy(g_keySnapshot, bytes, kKeyBytes);
234	        g_haveSnapshot = true;
235	        logVerifyHeader(g_keySnapshot);
236	        return;
237	    }
238	    if (g_progress > kKeyBytes) {
239	        logVerifyFailed("offset past end of key");
240	        std::abort();
241	    }
242	    const std::size_t remaining = kKeyBytes - g_progress;
243	    if (count != remaining) {
244	        logVerifyFailed("write length does not match the bytes still pending");
245	        std::abort();
246	    }
247	    if (std::memcmp(g_keySnapshot + g_progress, bytes, remaining) != 0) {
248	        logVerifyFailed("buffer is not the same key (key was regenerated?)");
249	        std::abort();
250	    }
251	}
252	
253	void resetWriteBookkeeping() {
254	    g_haveSnapshot = false;
255	    g_progress = 0;
256	}
257	
258	// Outcome of one scripted write() call.
259	enum class WriteOutcome {
260	    kPass,       // behave as the real syscall with the given count
261	    kShort,      // behave as the real syscall but cap the count
262	    kEintr,      // report a recoverable interrupt, nothing written
263	    kEio,        // report an irrecoverable I/O error
264	    kZero,       // report zero bytes with data still pending
265	};
266	
267	struct ScriptedCall {
268	    WriteOutcome outcome;
269	    long limit;  // valid for kShort
270	};
271	
272	// Parse the next EF_TEST_WRITE_SCRIPT token. Returns false once the script is
273	// exhausted (the caller should then behave normally).
274	bool nextScriptedCall(ScriptedCall& call) {
275	    static char script[512];
276	    static bool initialized = false;
277	    static char* saveptr = nullptr;
278	
279	    if (!initialized) {
280	        const char* raw = std::getenv("EF_TEST_WRITE_SCRIPT");
281	        if (raw == nullptr) {
282	            script[0] = '\0';
283	        } else {
284	            std::strncpy(script, raw, sizeof(script) - 1);
285	            script[sizeof(script) - 1] = '\0';
286	        }
287	        saveptr = script;
288	        initialized = true;
289	    }
290	
291	    char* token = ::strtok_r(nullptr, ",", &saveptr);
292	    if (token == nullptr) {
293	        return false;
294	    }
295	    if (std::strcmp(token, "ok") == 0) {
296	        call.outcome = WriteOutcome::kPass;
297	    } else if (std::strcmp(token, "intr") == 0) {
298	        call.outcome = WriteOutcome::kEintr;
299	    } else if (std::strcmp(token, "eio") == 0) {
300	        call.outcome = WriteOutcome::kEio;
301	    } else if (std::strcmp(token, "zero") == 0) {
302	        call.outcome = WriteOutcome::kZero;
303	    } else {
304	        char* end = nullptr;
305	        long limit = std::strtol(token, &end, 10);
306	        if (end != token && *end == '\0' && limit > 0) {
307	            call.outcome = WriteOutcome::kShort;
308	            call.limit = limit;
309	        } else {
310	            // An unknown token is a test-script bug: fail loudly rather than
311	            // silently behave as a normal write.
312	            std::fprintf(stderr,
313	                         "envelopefile_testable: invalid write script token "
314	                         "'%s'\n", token);
315	            call.outcome = WriteOutcome::kEio;
316	        }
317	    }
318	    return true;
319	}
320	
321	}  // namespace
322	
323	int __wrap_open(const char* path, int flags, ...) {
324	    mode_t mode = 0;
325	    if ((flags & O_CREAT) != 0) {
326	        va_list args;
327	        va_start(args, flags);
328	        mode = static_cast<mode_t>(va_arg(args, int));
329	        va_end(args);
330	    }
331	    int fd = __real_open(path, flags, mode);
332	    if (fd != -1 && (flags & O_CREAT) != 0 && (flags & O_EXCL) != 0 &&
333	        isKeyPath(path)) {
334	        g_keyFd = fd;
335	        resetWriteBookkeeping();
336	    }
337	    return fd;
338	}
339	
340	ssize_t __wrap_write(int fd, const void* buffer, size_t count) {
341	    if (!isKeyFd(fd)) {
342	        return __real_write(fd, buffer, count);
343	    }
344	
345	    verifyIncomingBuffer(buffer, count);
346	
347	    const size_t requested = count;  // caller's original length for the log
348	    ScriptedCall call;
349	    const bool scripted = nextScriptedCall(call);
350	    if (scripted) {
351	        switch (call.outcome) {
352	            case WriteOutcome::kEintr:
353	                logCall(g_progress, requested, -1, EINTR);
354	                errno = EINTR;
355	                return -1;
356	            case WriteOutcome::kEio:
357	                logCall(g_progress, requested, -1, EIO);
358	                errno = EIO;
359	                return -1;
360	            case WriteOutcome::kZero:
361	                logCall(g_progress, requested, 0, 0);
362	                errno = 0;
363	                return 0;
364	            case WriteOutcome::kShort:
365	                if (count > static_cast<size_t>(call.limit)) {
366	                    count = static_cast<size_t>(call.limit);
367	                }
368	                break;
369	            case WriteOutcome::kPass:
370	                break;
371	        }
372	    } else {
373	        // Legacy single-knob injection, kept for the existing regressions.
374	        if (envFlagSet("EF_TEST_FAIL_WRITE")) {
375	            logCall(g_progress, requested, -1, EIO);
376	            errno = EIO;
377	            return -1;
378	        }
379	        const char* chunk = std::getenv("EF_TEST_PARTIAL_WRITE");
380	        if (chunk != nullptr) {
381	            const long limit = std::atol(chunk);
382	            if (limit > 0 && count > static_cast<size_t>(limit)) {
383	                count = static_cast<size_t>(limit);
384	            }
385	        }
386	    }
387	
388	    ssize_t result = __real_write(fd, buffer, count);
389	    logCall(g_progress, requested, result, errno);
390	    if (result > 0) {
391	        g_progress += static_cast<std::size_t>(result);
392	    }
393	    return result;
394	}
395	
396	int __wrap_fsync(int fd) {
397	    if (isKeyFd(fd) && envFlagSet("EF_TEST_FAIL_FSYNC")) {
398	        errno = EIO;
399	        return -1;
400	    }
401	    return __real_fsync(fd);
402	}
403	
404	int __wrap_close(int fd) {
405	    const bool wasKeyFd = isKeyFd(fd);
406	    const int result = __real_close(fd);
407	    if (wasKeyFd) {
408	        g_keyFd = -1;
409	        if (envFlagSet("EF_TEST_FAIL_CLOSE")) {
410	            // The descriptor is already closed for real; only the reported
411	            // status is faked, mirroring a genuine close(2) failure.
412	            errno = EIO;
413	            return -1;
414	        }
415	    }
416	    return result;
417	}
418	
419	int __wrap_RAND_bytes(unsigned char* buf, int num) {
420	    if (!envFlagSet("EF_TEST_FAIL_RAND")) {
421	        const int result = __real_RAND_bytes(buf, num);
422	        if (result == 1) {
423	            g_randBuf = buf;
424	            g_randBufSize = num;
425	            char line[96];
426	            std::snprintf(line, sizeof(line),
427	                          "RAND %d partial=0 result=ok", num);
428	            logKeyLine(line);
429	        }
430	        return result;
431	    }
432	
433	    g_randBuf = buf;
434	    g_randBufSize = num;
435	
436	    // Simulate a CSPRNG that wrote some bytes before dying: the caller must
437	    // not mistake the partial fill for a valid key.
438	    long partial = 0;
439	    const char* raw = std::getenv("EF_TEST_RAND_PARTIAL");
440	    if (raw != nullptr) {
441	        partial = std::atol(raw);
442	        if (partial < 0) {
443	            partial = 0;
444	        }
445	        if (partial > num) {
446	            partial = num;
447	        }
448	    }
449	    for (long i = 0; i < partial; ++i) {
450	        buf[i] = 0xA5;
451	    }
452	
453	    // Start from an empty error queue, then optionally leave a descriptive
454	    // OpenSSL error so the "detail" and "no detail" messages are both
455	    // exercised deterministically.
456	    ERR_clear_error();
457	    if (envFlagSet("EF_TEST_RAND_ERROR_DETAIL")) {
458	#if OPENSSL_VERSION_NUMBER >= 0x30000000L
459	        ERR_raise(ERR_LIB_RAND, 0x7f);
460	#else
461	        ERR_put_error(ERR_LIB_RAND, 0, 0x7f, __FILE__, __LINE__);
462	#endif
463	    }
464	
465	    char line[96];
466	    std::snprintf(line, sizeof(line), "RAND %d partial=%ld result=fail",
467	                  num, partial);
468	    logKeyLine(line);
469	    return 0;
470	}
471	
472	void __wrap_OPENSSL_cleanse(void* ptr, size_t len) {
473	    if (ptr != nullptr && ptr == g_randBuf) {
474	        char line[96];
475	        std::snprintf(line, sizeof(line), "CLEANSED-KEY %zu", len);
476	        logKeyLine(line);
477	        // Record how far the save had progressed when the wipe happened, so
478	        // the test driver can prove a successful save was not preceded by
479	        // the wipe (which would have saved wiped data).
480	        char state[96];
481	        std::snprintf(state, sizeof(state),
482	                      "CLEANSE-STATE writes=%zu keyfd=%s",
483	                      g_progress, g_keyFd == -1 ? "closed" : "open");
484	        logKeyLine(state);
485	        // The buffer is about to be released; do not match a stale address.
486	        g_randBuf = nullptr;
487	        g_randBufSize = 0;
488	    }
489	    __real_OPENSSL_cleanse(ptr, len);
490	}
491	
492	}  // extern "C"
